from functools import lru_cache
H,W=15,7
cells={(r,c) for r in range(H) for c in range(W) if grid[r][c]==2}
pieces=[('0',1,1),('7',3,2),('6a',1,4),('6b',1,4),('4',6,2),('8',2,2),('1',2,5)]
# rectangles orientations
piece_shapes={name: list({(h,w),(w,h)}) for name,h,w in pieces}
placements={}
for name,h,w in pieces:
    placements[name]=[]
    for hh,ww in piece_shapes[name]:
        for r in range(H-hh+1):
            for c in range(W-ww+1):
                ps={(rr,cc) for rr in range(r,r+hh) for cc in range(c,c+ww)}
                if ps<=cells: placements[name].append((r,c,hh,ww,ps))
# Exact tilings, canonical order fixed pieces names (a repeated interchangeable pieces avoid dup via id names)
solutions=[]

def rec(rem_cells, rem_names, sol):
    if not rem_cells:
        if not rem_names: solutions.append(sol.copy())
        return
    if not rem_names: return
    r,c=min(rem_cells)
    for name in rem_names:
        if name in ('6a','6b') and name=='6b' and '6a' in rem_names: continue
        for rr,cc,hh,ww,ps in placements[name]:
            if (rr,cc)!=(r,c): continue
            if ps<=rem_cells:
                sol.append((name,rr,cc,hh,ww))
                rec(rem_cells-ps,[n for n in rem_names if n!=name],sol)
                sol.pop()
rec(cells,[p[0] for p in pieces],[])
len(solutions)
